Fixes: e21fe3a52692 ("scsi: hisi_sas: add initialisation for v3 pci-based controller")
Signed-off-by: Xingui Yang <yangxingui@huawei.com>
Signed-off-by: Yihang Li <liyihang9@huawei.com>
Link: https://patch.msgid.link/20260305064039.4096775-1-liyihang9@huawei.com
Signed-off-by: Martin K. Petersen <martin.petersen@oracle.com>

Here is the root cause:
The driver incorrectly set `shost->max_channel = 1` during initialization, indicating support for two channels (0 and 1). However, the Hisi SAS controller only uses channel 0. When commit 37c4e72b0651 updated `sas_user_scan()` to iterate channels 1 through `shost->max_channel`, scanning channel 1 triggered a path that tried to access uninitialized domain device structures, leading to a NULL pointer dereference in `sas_find_dev_by_rphy()`.

Here is the patch:

 static int
 hisi_sas_v3_probe(struct pci_dev *pdev, const struct pci_device_id *id)
 {
 	struct Scsi_Host *shost;
 	struct hisi_hba *hisi_hba;
 	struct device *dev = &pdev->dev;
 	struct asd_sas_phy **arr_phy;
 	struct asd_sas_port **arr_port;
 	struct sas_ha_struct *sha;
 	int rc, phy_nr, port_nr, i;

 	rc = pcim_enable_device(pdev);
 	if (rc)
 		goto err_out;

 	pci_set_master(pdev);

 	rc = pcim_iomap_regions(pdev, 1 << BAR_NO_V3_HW, DRV_NAME);
 	if (rc)
 		goto err_out;

 	rc = dma_set_mask_and_coherent(&pdev->dev, DMA_BIT_MASK(64));
 	if (rc) {
 		dev_err(dev, "No usable DMA addressing method\n");
 		rc = -ENODEV;
 		goto err_out;
 	}

 	shost = hisi_sas_shost_alloc_pci(pdev);
 	if (!shost) {
 		rc = -ENOMEM;
 		goto err_out;
 	}

 	sha = SHOST_TO_SAS_HA(shost);
 	hisi_hba = shost_priv(shost);
 	dev_set_drvdata(dev, sha);

 	hisi_hba->regs = pcim_iomap_table(pdev)[BAR_NO_V3_HW];
 	if (!hisi_hba->regs) {
 		dev_err(dev, "cannot map register\n");
 		rc = -ENOMEM;
 		goto err_out_free_host;
 	}

 	phy_nr = port_nr = hisi_hba->n_phy;

 	arr_phy = devm_kcalloc(dev, phy_nr, sizeof(void *), GFP_KERNEL);
 	arr_port = devm_kcalloc(dev, port_nr, sizeof(void *), GFP_KERNEL);
 	if (!arr_phy || !arr_port) {
 		rc = -ENOMEM;
 		goto err_out_free_host;
 	}

 	sha->sas_phy = arr_phy;
 	sha->sas_port = arr_port;
 	sha->shost = shost;
 	sha->lldd_ha = hisi_hba;

 	shost->transportt = hisi_sas_stt;
 	shost->max_id = HISI_SAS_MAX_DEVICES;
 	shost->max_lun = ~0;
-	shost->max_channel = 1;
+	shost->max_channel = 0;
 	shost->max_cmd_len = HISI_SAS_MAX_CDB_LEN;
 	shost->can_queue = HISI_SAS_UNRESERVED_IPTT;
 	shost->cmd_per_lun = HISI_SAS_UNRESERVED_IPTT;
 	if (hisi_hba->iopoll_q_cnt)
 		shost->nr_maps = 3;
 	else
 		shost->nr_maps = 1;

 	sha->sas_ha_name = DRV_NAME;
 	sha->dev = dev;
 	sha->sas_addr = &hisi_hba->sas_addr[0];
 	sha->num_phys = hisi_hba->n_phy;

 	for (i = 0; i < hisi_hba->n_phy; i++) {
 		sha->sas_phy[i] = &hisi_hba->phy[i].sas_phy;
 		sha->sas_port[i] = &hisi_hba->port[i].sas_port;
 	}

 	if (hisi_hba->prot_mask) {
 		dev_info(dev, "Registering for DIF/DIX prot_mask=0x%x\n",
 			 prot_mask);
 		scsi_host_set_prot(hisi_hba->shost, prot_mask);
 		if (hisi_hba->prot_mask & HISI_SAS_DIX_PROT_MASK)
 			scsi_host_set_guard(hisi_hba->shost,
 					    SHOST_DIX_GUARD_CRC);
 	}

 	rc = interrupt_preinit_v3_hw(hisi_hba);
 	if (rc)
 		goto err_out_free_host;

 	rc = scsi_add_host(shost, dev);
 	if (rc)
 		goto err_out_free_host;

 	rc = sas_register_ha(sha);
 	if (rc)
 		goto err_out_remove_host;

 	rc = hisi_sas_v3_init(hisi_hba);
 	if (rc)
 		goto err_out_unregister_ha;

 	scsi_scan_host(shost);
 	if (hisi_sas_debugfs_enable)
 		debugfs_init_v3_hw(hisi_hba);

 	pm_runtime_set_autosuspend_delay(dev, 5000);
 	pm_runtime_use_autosuspend(dev);
 	/*
 	 * For the situation that there are ATA disks connected with SAS
 	 * controller, it additionally creates ata_port which will affect the
 	 * child_count of hisi_hba->dev. Even if suspended all the disks,
 	 * ata_port is still and the child_count of hisi_hba->dev is not 0.
 	 * So use pm_suspend_ignore_children() to ignore the effect to
 	 * hisi_hba->dev.
 	 */
 	pm_suspend_ignore_children(dev, true);
 	pm_runtime_put_noidle(&pdev->dev);

 	return 0;

 err_out_unregister_ha:
 	sas_unregister_ha(sha);
 err_out_remove_host:
 	scsi_remove_host(shost);
 err_out_free_host:
 	hisi_sas_free(hisi_hba);
 	scsi_host_put(shost);
 err_out:
 	return rc;
 }



